<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class TrainingProgramReview extends Model{protected $fillable=['training_program_id','review_date','review_type','committee_id','committee_meeting_id','copasst_or_vigia_participation','senior_management_employee_id','senior_management_participation','conclusions','improvement_actions','document_path','reviewed_by'];protected $casts=['review_date'=>'date','copasst_or_vigia_participation'=>'boolean','senior_management_participation'=>'boolean'];public function program(){return$this->belongsTo(TrainingProgram::class,'training_program_id');}public function committee(){return$this->belongsTo(Committee::class);}public function meeting(){return$this->belongsTo(CommitteeMeeting::class,'committee_meeting_id');}}
